<span class="line"><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">        limit_rate </span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;">500k</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">;</span></span>
